/// <summary>
/// AVA/WEN/20250109    AVA_012791_CredManBlockExclusionRules
/// </summary>
/// <param name = "_salesId">SalesId</param>
/// <param name = "_salesTotal">AmountMst</param>
/// <param name = "_amountIncreased">NoYes</param>
/// <param name = "_holdType">CredManHoldType</param>
/// <returns>CredManTable</returns>
protected CredManTable initTmpCredManTable(
    SalesId _salesId,
    AmountMST _salesTotal,
    NoYes _amountIncreased,
    CredManHoldType _holdType
    )
{
    CredManTable tmpCredManTable;
    SalesTotals                     salesTotalsSales;

    tmpCredManTable.setTmp();

    tmpCredManTable = next initTmpCredManTable(_salesId, _salesTotal, _amountIncreased, _holdType);
    salesTotalsSales = salesTotals::construct(SalesTable::find(tmpCredManTable.SalesId));
    salesTotalsSales.calc();

    tmpCredManTable.AVANetTotal = salesTotalsSales.totalBalance() + salesTotalsSales.totalMarkup();

    return tmpCredManTable;
}
